import{_ as o,r as a,o as r,c as l,e as s,a as p,s as c}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"Sorting Records - October CMS - 4.x","titleTemplate":false,"description":"Learn how to sort and structure records in a list.","frontmatter":{"subtitle":"Learn how to sort and structure records in a list."},"headers":[{"level":2,"title":"Configuring a Behavior","slug":"configuring-a-behavior","link":"#configuring-a-behavior","children":[]},{"level":2,"title":"Supported Model Types","slug":"supported-model-types","link":"#supported-model-types","children":[{"level":3,"title":"Nested Set","slug":"nested-set","link":"#nested-set","children":[]},{"level":3,"title":"Simple Tree","slug":"simple-tree","link":"#simple-tree","children":[]},{"level":3,"title":"Sortable Model","slug":"sortable-model","link":"#sortable-model","children":[]}]},{"level":2,"title":"Sorting Related Records","slug":"sorting-related-records","link":"#sorting-related-records","children":[{"level":3,"title":"Sortable Relation Model Trait","slug":"sortable-relation-model-trait","link":"#sortable-relation-model-trait","children":[]}]}],"relativePath":"4.x/extend/lists/structures.md","filePath":"4.x/extend/lists/structures.md"}'),i={name:"4.x/extend/lists/structures.md"};function d(u,e,h,k,g,m){const n=a("pre-heading"),t=a("post-heading");return r(),l("div",null,[s(n),e[0]||(e[0]=p("h1",null,"Sorting Records",-1)),s(t),e[1]||(e[1]=c(`<p>October CMS provides features for sorting and reordering database records. For behaviors that support structured lists, you can define a <strong>structure</strong> property to enable the feature. Various <a href="./../database/traits.html">model traits</a> are used to support reordering including nested sets, simple trees and sortable models.</p><h2 id="configuring-a-behavior"><a href="#configuring-a-behavior" class="header-anchor">#</a> Configuring a Behavior</h2><p>The <a href="./list-controller.html">List Controller</a> and <a href="./../forms/form-controller.html">Relation Controller</a> backend behaviors currently support the option to reorder records using the <strong>structure</strong> property in the relevant definition. When defined, the page displays a list of records with a drag handle allowing them to be sorted and restructured.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token comment"># config_list.yaml</span>

<span class="token comment"># ...</span>

<span class="token key atrule">structure</span><span class="token punctuation">:</span>
    <span class="token key atrule">showTree</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>
    <span class="token key atrule">showReorder</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>
    <span class="token key atrule">showSorting</span><span class="token punctuation">:</span> <span class="token boolean important">false</span>
    <span class="token key atrule">maxDepth</span><span class="token punctuation">:</span> <span class="token number">2</span>
</code></pre></div><p>The configuration properties listed below can be used.</p><div class="table"><table tabindex="0"><thead><tr><th>Property</th><th>Description</th></tr></thead><tbody><tr><td><strong>showTree</strong></td><td>displays a tree hierarchy for parent/child records. Default: <code>true</code></td></tr><tr><td><strong>treeExpanded</strong></td><td>if tree nodes should be expanded by default. Default: <code>true</code></td></tr><tr><td><strong>showReorder</strong></td><td>displays an interface for reordering records. Default: <code>true</code></td></tr><tr><td><strong>showSorting</strong></td><td>allows sorting records, disables the structure when sorted. Default: <code>true</code></td></tr><tr><td><strong>maxDepth</strong></td><td>defines the maximum levels allowed for reordering. Default: <code>null</code></td></tr><tr><td><strong>dragRow</strong></td><td>allow dragging the entire row in addition to the reorder handle. Default: <code>true</code></td></tr><tr><td><strong>permissions</strong></td><td>the <a href="./../../extend/backend/permissions.html">permissions</a> that the current backend user must have to modify the structure. Supports either a string for a single permission or an array of permissions of which only one is needed to grant access.</td></tr></tbody></table></div><h2 id="supported-model-types"><a href="#supported-model-types" class="header-anchor">#</a> Supported Model Types</h2><p>Depending on the requirements, a different model interface can be used for managing nested and sorted records. The behavior will adapt depending on which trait is implemented.</p><h3 id="nested-set"><a href="#nested-set" class="header-anchor">#</a> Nested Set</h3><p>Use the <code>NestedTree</code> trait when a fixed structure is needed. This includes parent-child relationships and when records need to be displayed in a specific order.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Category</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>NestedTree</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Read more about the <code>NestedTree</code> trait in the <a href="./../database/traits.html">database documentation</a>.</p><h3 id="simple-tree"><a href="#simple-tree" class="header-anchor">#</a> Simple Tree</h3><p>Use the <code>SimpleTree</code> trait when a basic parent-child relationship is needed.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Category</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>SimpleTree</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Read more about the <code>SimpleTree</code> trait in the <a href="./../database/traits.html">database documentation</a>.</p><h3 id="sortable-model"><a href="#sortable-model" class="header-anchor">#</a> Sortable Model</h3><p>Use the <code>Sortable</code> trait when records need to be displayed in a specific order.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>Sortable</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Read more about the <code>Sortable</code> trait in the <a href="./../database/traits.html">database documentation</a>.</p><h2 id="sorting-related-records"><a href="#sorting-related-records" class="header-anchor">#</a> Sorting Related Records</h2><p>Sorting related records is possible using the <a href="./../forms/relation-controller.html">Relation Controller</a> using the <strong>structure</strong> property. The supported relation types are listed below.</p><ul><li><a href="./../database/relations.html#relation-one-to-many">Has Many</a> uses the <code>Sortable</code> trait on the related model.</li><li><a href="./../database/relations.html#relation-many-to-many">Belongs To Many</a> uses the <code>SortableRelation</code> trait on the parent model (see below).</li></ul><h3 id="sortable-relation-model-trait"><a href="#sortable-relation-model-trait" class="header-anchor">#</a> Sortable Relation Model Trait</h3><p>Use the <code>SortableRelation</code> model trait when records need to be sorted inside a pivot table, such as a <a href="./../database/relations.html#many-to-many">Belongs To Many</a> relation type. This trait requires the <code>pivotSortable</code> property to be defined in the relationship where the value is the sortable column name found in the pivot table.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>SortableRelation</span><span class="token punctuation">;</span>

    <span class="token comment">/**
     * @var array belongsToMany
     */</span>
    <span class="token keyword">public</span> <span class="token variable">$belongsToMany</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;roles&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token class-name static-context">Role</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;table&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;users_roles&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;pivotSortable&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;sort_order&#39;</span><span class="token punctuation">,</span>
        <span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Then inside your relation configuration, you should enable the <code>showReorder</code> property and disable the <code>showTree</code> property.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">roles</span><span class="token punctuation">:</span>
    <span class="token comment">#...</span>
    <span class="token key atrule">structure</span><span class="token punctuation">:</span>
        <span class="token key atrule">showReorder</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>
        <span class="token key atrule">showTree</span><span class="token punctuation">:</span> <span class="token boolean important">false</span>
</code></pre></div>`,28))])}const y=o(i,[["render",d]]);export{f as __pageData,y as default};
